import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // ===== BACKDROP (7 x 5.5 plane at z=-1.5) =====
  const backdropGeometry = new THREE.PlaneGeometry(7, 5.5);
  const backdropMaterial = new THREE.MeshBasicMaterial({
    color: 0x0b0b10,
  });
  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -1.5;
  group.add(backdrop);

  // ===== CAPTION KICKER (JetBrains Mono 700, 18px) =====
  const caption = ctx.fontAtlas.createText("NOVA ATELIER / CALIBRE PROGRAM", {
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 700,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: '#e8ecf2',
    align: 'center',
  });
  caption.position.y = 1.15;
  caption.position.z = 0;
  group.add(caption);

  // ===== HERO TEXT GROUP (Lora 600, 124px, em height 0.62) =====
  const heroGroup = new THREE.Group();
  heroGroup.position.y = 0.4;

  // Word 1: "TIME," with z-offset 0.12 (front parallax)
  const word1 = ctx.fontAtlas.createText("TIME,", {
    fontFamily: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.01,
    lineHeight: 1.05,
    color: '#e8ecf2',
    align: 'center',
  });
  word1.position.z = 0.12;
  heroGroup.add(word1);

  // Word 2: "MACHINED." with z-offset -0.12 (back parallax)
  const word2 = ctx.fontAtlas.createText("MACHINED.", {
    fontFamily: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.01,
    lineHeight: 1.05,
    color: '#e8ecf2',
    align: 'center',
  });
  word2.position.z = -0.12;
  heroGroup.add(word2);

  group.add(heroGroup);

  // ===== ACCENT UNDERLINE (2.6 x 0.045 plane, #ff2a38, emissive 1.2, at y=-0.05 under hero) =====
  const underlineGeometry = new THREE.PlaneGeometry(2.6, 0.045);
  const underlineMaterial = new THREE.MeshBasicMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.2,
  });
  const underline = new THREE.Mesh(underlineGeometry, underlineMaterial);
  underline.position.y = 0.35; // 0.4 (hero y) - 0.05
  underline.position.z = 0.1;
  underline.position.x = -1.3; // Anchor at left edge for left-to-right growth
  underline.scale.x = 0; // Start invisible
  group.add(underline);

  // ===== SUBHEAD (JetBrains Mono 400, 40px, em height 0.2) =====
  const subhead = ctx.fontAtlas.createText("Every calibre begins as a solid billet.", {
    fontFamily: 'JetBrains Mono',
    fontSize: 40,
    fontWeight: 400,
    letterSpacing: 0.02,
    lineHeight: 1.35,
    color: '#e8ecf2',
    align: 'center',
  });
  subhead.position.y = -0.45; // Start raised (-0.65 + 0.2) for fade-up animation
  subhead.position.z = 0;

  // Ensure subhead material supports transparency for fade
  if (subhead.material) {
    subhead.material.transparent = true;
    subhead.material.opacity = 0;
  } else if (subhead.children && subhead.children.length > 0) {
    subhead.children.forEach(child => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
  }

  group.add(subhead);

  // ===== APPLY KINETIC-TEXT CINEMATIC PRIMITIVE =====
  // Handles per-glyph entrance (y +0.35→0, opacity 0→1, 700ms, 60ms stagger)
  // and weighted-settle (scale 1.04→1.0, 900ms) on hero group
  if (ctx.primitives && ctx.primitives['kinetic-text']) {
    ctx.primitives['kinetic-text'](heroGroup, {
      staggerMs: 60,
      riseUnits: 0.35,
    });
  }

  // ===== ANIMATIONS =====
  const timeline = gsap.timeline();

  // Underline animation: scaleX 0→1 left-anchored over 500ms
  // Starting 120ms after last glyph lands (~700ms)
  const underlineStartTime = 0.82; // 0.7 (hero end) + 0.12 (delay)

  timeline.to(
    { scale: 0, x: -1.3 },
    {
      scale: 1,
      x: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
      onUpdate: function() {
        const target = this.targets()[0];
        underline.scale.x = target.scale;
        underline.position.x = target.x;
      },
    },
    underlineStartTime
  );

  // Subhead fade-up: opacity 0→1, y +0.2→0 (position -0.45→-0.65) over 500ms
  timeline.to(
    subhead.position,
    {
      y: -0.65,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    },
    underlineStartTime
  );

  // Fade in subhead material
  const setSubheadOpacity = (val) => {
    if (subhead.material) {
      subhead.material.opacity = val;
    } else if (subhead.children) {
      subhead.children.forEach(child => {
        if (child.material) child.material.opacity = val;
      });
    }
  };

  timeline.to(
    { opacity: 0 },
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
      onUpdate: function() {
        setSubheadOpacity(this.targets()[0].opacity);
      },
    },
    underlineStartTime
  );

  // ===== CLEANUP =====
  group.userData.cleanup = () => {
    timeline.kill();
    backdropGeometry.dispose();
    backdropMaterial.dispose();
    underlineGeometry.dispose();
    underlineMaterial.dispose();
  };

  group.userData.handlers = {};

  return group;
}
